INSERT INTO public.restaurants(id,status,origin_name,naver_name,approved_name,lat,lng,geocoding_success,jibun_address,categories,tzuyang_review,trace_id,youtube_link,evaluation_results,source_type,created_by,updated_by_admin_id,phone) SELECT id,status,origin_name,naver_name,approved_name,lat,lng,geocoding_success,jibun_address,categories,tzuyang_review,trace_id,youtube_link,evaluation_results,source_type,created_by,updated_by_admin_id,phone FROM jsonb_populate_record(NULL::public.restaurants,'{"id": "efe80f2a-965f-4418-a4f7-3f1a78b0b60c", "status": "pending", "origin_name": "fixture branch", "naver_name": "fixture branch", "approved_name": "fixture branch", "lat": 37.5, "lng": 127, "geocoding_success": true, "jibun_address": "synthetic business address", "categories": ["\ud55c\uc2dd"], "tzuyang_review": "fixture review", "trace_id": "e38f87e71cfe4390b4687c9bec03a11e", "youtube_link": "https://www.youtube.com/watch?v=ABCDEFGHIJK", "evaluation_results": {"visit_authenticity": {"eval_value": 1, "eval_basis": "fixture evidence"}, "rb_inference_score": {"eval_value": 1, "eval_basis": "fixture evidence"}, "review_faithfulness_score": {"eval_value": 1, "eval_basis": "fixture evidence"}, "rb_grounding_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "category_validity_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "category_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "location_match_TF": {"origin_name": "fixture branch", "eval_value": true, "match_status": "matched", "evidence_families": ["source_geo", "provider_candidate"]}}, "source_type": "crawler", "created_by": null, "updated_by_admin_id": null, "phone": "02-777-0000"}'::jsonb);INSERT INTO pipeline_control.restaurant_review_policy(singleton,version,enabled,operator_id,batch_size,daily_limit) VALUES(true,7,true,'00000000-0000-0000-0000-000000000065',1,1);INSERT INTO pipeline_control.restaurant_review_runs(id,request_id,policy_version) VALUES('00000000-0000-4000-8000-000000000201',gen_random_uuid(),7);INSERT INTO pipeline_control.restaurant_review_items(id,run_id,restaurant_id,fingerprint,applied_fingerprint,decision,reason,state,input_sha256,gemini_decision) SELECT '00000000-0000-4000-8000-000000000202','00000000-0000-4000-8000-000000000201',id,'earlier-input-fingerprint',pipeline_control.restaurant_review_fingerprint(to_jsonb(t)),'approve','daily_limit','succeeded',repeat('a',64),'{"outcome":"deferred"}'::jsonb FROM public.restaurants t WHERE id='efe80f2a-965f-4418-a4f7-3f1a78b0b60c';SELECT set_config('fixture.original_fp',pipeline_control.restaurant_review_fingerprint((SELECT to_jsonb(t) FROM public.restaurants t WHERE id='efe80f2a-965f-4418-a4f7-3f1a78b0b60c')),true);INSERT INTO public.restaurants(id,status,origin_name,naver_name,approved_name,lat,lng,geocoding_success,jibun_address,categories,tzuyang_review,trace_id,youtube_link,evaluation_results,source_type,created_by,updated_by_admin_id,phone) SELECT id,status,origin_name,naver_name,approved_name,lat,lng,geocoding_success,jibun_address,categories,tzuyang_review,trace_id,youtube_link,evaluation_results,source_type,created_by,updated_by_admin_id,phone FROM jsonb_populate_record(NULL::public.restaurants,'{"id": "b93a0195-aa3d-4995-a399-d7cd93faa32a", "status": "approved", "origin_name": "another fixture branch", "naver_name": "another fixture branch", "approved_name": "another fixture branch", "lat": 37.5, "lng": 127, "geocoding_success": true, "jibun_address": "synthetic business address", "categories": ["\ud55c\uc2dd"], "tzuyang_review": "fixture review", "trace_id": "eee8ddf532cf46c2bf21edc2bb6738af", "youtube_link": "https://www.youtube.com/watch?v=LMNOPQRSTUV", "evaluation_results": {"visit_authenticity": {"eval_value": 1, "eval_basis": "fixture evidence"}, "rb_inference_score": {"eval_value": 1, "eval_basis": "fixture evidence"}, "review_faithfulness_score": {"eval_value": 1, "eval_basis": "fixture evidence"}, "rb_grounding_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "category_validity_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "category_TF": {"eval_value": true, "eval_basis": "fixture evidence"}, "location_match_TF": {"origin_name": "fixture branch", "eval_value": true, "match_status": "matched", "evidence_families": ["source_geo", "provider_candidate"]}}, "source_type": "crawler", "created_by": null, "updated_by_admin_id": null, "phone": "02-777-0000"}'::jsonb);SET LOCAL ROLE service_role;SELECT set_config('request.jwt.claim.role','',true);SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);DO $test$ DECLARE a jsonb;b jsonb;request uuid:=gen_random_uuid();BEGIN IF pipeline_control.restaurant_review_fingerprint((SELECT to_jsonb(t) FROM public.restaurants t WHERE id='efe80f2a-965f-4418-a4f7-3f1a78b0b60c'))<>current_setting('fixture.original_fp') OR pipeline_control.restaurant_review_decision((SELECT to_jsonb(t) FROM public.restaurants t WHERE id='efe80f2a-965f-4418-a4f7-3f1a78b0b60c'))<>'hold:duplicate_requires_review' THEN RAISE EXCEPTION 'REVIEW_FIX_DEFERRED_SETUP';END IF;a:=public.restaurant_review_automation_tick(request);IF (a->>'held')::int<>1 OR (a->>'scanned')::int<>1 OR (SELECT status FROM public.restaurants WHERE id='efe80f2a-965f-4418-a4f7-3f1a78b0b60c')<>'hold' OR NOT EXISTS(SELECT 1 FROM pipeline_control.restaurant_review_items WHERE id='00000000-0000-4000-8000-000000000202' AND state='applied' AND decision='hold' AND reason='duplicate_requires_review' AND gemini_decision->>'outcome'='hold' AND fingerprint<>applied_fingerprint) THEN RAISE EXCEPTION 'REVIEW_FIX_DEFERRED_NOT_APPLIED';END IF;b:=public.restaurant_review_automation_tick(request);IF a IS DISTINCT FROM b THEN RAISE EXCEPTION 'REVIEW_FIX_DEFERRED_REQUEST_CAS';END IF;b:=public.restaurant_review_automation_tick(gen_random_uuid());IF (b->>'scanned')::int<>0 OR EXISTS(SELECT 1 FROM pipeline_control.restaurant_review_items WHERE state IN('queued','running')) THEN RAISE EXCEPTION 'REVIEW_FIX_DEFERRED_ONE_BATCH';END IF;END $test$;ROLLBACK;